type Model = { count: Int where it >= 0 }

type Msg = Increment | Decrement | Reset

fn init() -> Model = Model { count: 0 }

fn update(m: Model, msg: Msg) -> Model = match msg {
  Increment => m with { count: m.count + 1 }
  Decrement => if m.count > 0 { m with { count: m.count - 1 } } else { m }
  Reset => init()
}

fn view(m: Model) -> Html[Msg] =
  Html.col(
    [
      Html.heading("Visit Counter"),
      Html.paragraph("You have visited this page " ++ m.count.toStr() ++ " times.")
    ]
  )

fn main() -> Int = init().count
